/**
 * Hilfe-Artikel zu den Lernpfaden „Daten erheben“ und „Mixed Methods“ (Erheben, Paket 1F, 08.11.2026): vier Artikel, jeder zugleich die Erklärung seiner Einheit
 * und der Ort von „Selbst machen“ (Aufgabe) und „Lösung“. Nur Deutsch und Englisch, jeder Text ein Textpaar P(de, en); die übrigen Sprachen fallen auf Englisch zurück.
 * Alle Zahlen, Tabellen und Zitate in „Selbst machen“ sind erfunden und so gekennzeichnet. Fachaussagen stützen sich auf docs/fachblaetter/BELEGE-ERHEBEN.json
 * (Fetters, Curry und Creswell 2013; Palinkas u. a. 2015; Schoonenboom und Johnson 2017; Schoonenboom 2023) und auf die Hilfe-Artikel „plausibilitaet“, „daten-check“,
 * „frage-mehrfachantworten“ und „frage-faelle“.
 */
import { P } from '../i18n/laufzeit';
import { a, falsch, mitnehmen, type Roh } from './artikel-roh';

export const ROH_ERHEBEN: Roh[] = [
  // ---------------------------------------------------------------- 1. Erhebungsmethode wählen
  a('eh-methode', 'verstehen', P('Befragen, beobachten, messen oder Dokumente auswerten? (Erhebungsmethode)', 'Ask, observe, measure or analyse documents? (data collection method)'),
    P('Erhebungsmethode Datenerhebung Befragung Beobachtung Messung Dokumentenanalyse Forschungsfrage Methode wählen Interview Fragebogen Tiefe Breite Sättigung Verallgemeinerung qualitativ quantitativ Mixed Methods', 'data collection method data collection survey observation measurement document analysis research question choosing a method interview questionnaire depth breadth saturation generalisation qualitative quantitative mixed methods'),
    [
      { h: P('Kurz', 'In brief') },
      P('Welche Erhebungsmethode passt, entscheidet die Forschungsfrage, nicht die Gewohnheit. Man kann Menschen befragen, ihr Verhalten beobachten, etwas messen oder vorhandene Dokumente auswerten. Wer wissen will, wie verbreitet etwas ist, braucht Breite (viele Fälle, eine Stichprobe, die für alle stehen kann). Wer verstehen will, wie und warum etwas geschieht, braucht Tiefe (wenige Fälle, genau betrachtet). Oft braucht eine Studie beides (Schoonenboom und Johnson, 2017).', 'The research question, not habit, decides which data collection method fits. You can ask people, observe their behaviour, measure something or analyse existing documents. Whoever wants to know how widespread something is needs breadth (many cases, a sample that can stand for everyone). Whoever wants to understand how and why something happens needs depth (few cases, looked at closely). Often a study needs both (Schoonenboom and Johnson, 2017).'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Die drei Forschungsfragen sind erfunden. Wählen Sie zu jeder eine Erhebungsmethode (Befragen, Beobachten, Messen oder Dokumente auswerten) und begründen Sie in einem Satz. Lesen Sie erst danach die Lösung.', 'The three research questions are invented. For each, choose a data collection method (ask, observe, measure or analyse documents) and give a one-sentence reason. Only then read the solution.'),
      { tabelle: { kopf: [P('Nr.', 'No.'), P('Forschungsfrage (erfunden)', 'Research question (invented)'), P('Ihre Methode und Begründung', 'Your method and reason')], zeilen: [
        ['1', P('Wie viele Studierende einer Hochschule nutzen die Bibliothek mindestens einmal in der Woche?', 'How many students at a university use the library at least once a week?'), '?'],
        ['2', P('Wie lange warten Patientinnen und Patienten in einer Ambulanz zwischen Ankunft und Aufruf?', 'How long do patients in an outpatient clinic wait between arrival and being called?'), '?'],
        ['3', P('Wie hat sich die Rede über Radwege in den Protokollen eines Gemeinderats seit 2015 verändert?', 'How has the talk about cycle paths changed in the minutes of a town council since 2015?'), '?']
      ] } },
      { h: P('Lösung', 'Solution') },
      { ol: [
        P('Befragen (Fragebogen mit einer Stichprobe der Studierenden). Gefragt ist ein Anteil in einer ganzen Gruppe; dafür braucht es Breite und eine Stichprobe, die für alle stehen kann.', 'Ask (questionnaire with a sample of the students). The question is a share in a whole group; that needs breadth and a sample that can stand for everyone.'),
        P('Messen (Zeitpunkte von Ankunft und Aufruf festhalten, zum Beispiel anhand der Aufrufe). Gefragt ist eine Dauer, die man direkt erfassen kann; Erinnerungen von Patienten wären ungenauer. Eine Beobachtung vor Ort ist die Alternative, wenn es keine Zeitstempel gibt.', 'Measure (record the times of arrival and being called, for example from the call-ups). The question is a duration that can be captured directly; patients’ memories would be less exact. Observing on site is the alternative if there are no time stamps.'),
        P('Dokumente auswerten (die Protokolle selbst). Die Quelle liegt vor und ist über Jahre gleich entstanden; Befragen würde nur Erinnerungen liefern.', 'Analyse documents (the minutes themselves). The source exists and was produced in the same way over the years; asking would only produce memories.')
      ] },
      P('Andere gut begründete Antworten sind möglich. Entscheidend ist, dass die Begründung von der Forschungsfrage ausgeht. Kommt zu Frage 1 die Folgefrage „Warum nutzen manche die Bibliothek nie?“ hinzu, passen Interviews dazu: Sie erreichen Tiefe, und die Studie wird eine Mixed-Methods-Studie.', 'Other well-founded answers are possible. What matters is that the reason starts from the research question. If question 1 is followed by “Why do some never use the library?”, interviews fit: they reach depth, and the study becomes a mixed methods study.'),
      { h: P('Breite und Tiefe', 'Breadth and depth') },
      P('Nach Palinkas und Kollegen (2015) zielen qualitative Verfahren meist auf Tiefe des Verstehens und stützen sich auf Sättigung: Man bezieht so lange weitere Fälle ein, bis nichts Neues mehr hinzukommt. Quantitative Verfahren zielen auf Breite und stützen sich auf Verallgemeinerbarkeit: Die Stichprobe soll die Grundgesamtheit abbilden. Die Auswahl der Fälle muss zu den Zielen und Annahmen des gewählten Verfahrens passen.', 'According to Palinkas and colleagues (2015), qualitative methods mostly aim at depth of understanding and rely on saturation: you keep including cases until nothing new is learned. Quantitative methods aim at breadth and rely on generalisability: the sample should represent the population. The selection of cases has to be consistent with the aims and assumptions of the chosen method.'),
      { h: P('Und die Mischung?', 'And mixing?') },
      P('Mixed-Methods-Forschung verbindet qualitative und quantitative Ansätze für Breite und Tiefe des Verstehens und für gegenseitige Absicherung (Schoonenboom und Johnson, 2017). Dazu raten die Autoren, mit mindestens einer Forschungsfrage zu beginnen und dann zu überlegen, wozu die Methoden gemischt werden: Man kann verschiedene Seiten einer einzigen Frage untersuchen oder getrennte, aber verwandte Fragen stellen.', 'Mixed methods research combines qualitative and quantitative approaches for breadth and depth of understanding and for corroboration (Schoonenboom and Johnson, 2017). The authors advise starting with at least one research question and then considering why the methods are mixed: one can examine different aspects of a single question or pose separate but related questions.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ul: [
        P('Statable wertet Daten aus, die schon vorliegen. Zum Planen einer Studie helfen die Artikel „Stichprobe“, „Repräsentativität“ und „Wurden die Personen einzeln oder in Gruppen gezogen?“ und die Karte „Fallzahl“ (Poweranalyse).', 'Statable analyses data that already exist. For planning a study, the articles “Sample”, “Representativeness” and “Were the people drawn individually or in groups?” and the card “Sample size” (power analysis) help.'),
        P('Ein Planungsassistent für Erhebungsmethoden (Design-Steckbrief) ist noch nicht gebaut.', 'A planning assistant for data collection methods (design profile) has not been built yet.')
      ] },
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Qualitative Studien brauchen einfach weniger Fälle, weil sie weniger genau sind.', 'Qualitative studies simply need fewer cases because they are less precise.'),
        P('Sie verfolgen ein anderes Ziel: Tiefe statt Breite. Die Zahl der Fälle richtet sich danach, wann nichts Neues mehr hinzukommt (Sättigung), nicht nach einer Formel zur Verallgemeinerung auf eine Grundgesamtheit.', 'They pursue a different aim: depth instead of breadth. The number of cases depends on when nothing new comes up any more (saturation), not on a formula for generalising to a population.')),
      falsch(P('Zuerst wählt man die Methode, die man am besten kennt, danach passt man die Frage an.', 'First you pick the method you know best, then you adapt the question.'),
        P('Es ist umgekehrt: Die Forschungsfrage kommt zuerst, dann folgt die Überlegung, welche Methode oder Mischung sie am besten beantwortet.', 'It is the other way round: the research question comes first, then the consideration of which method or mixture answers it best.')),
      { h: P('Quellen', 'Sources') },
      P('Schoonenboom, J. & Johnson, R. B. (2017). How to construct a mixed methods research design. Kölner Zeitschrift für Soziologie und Sozialpsychologie, 69 (Suppl 2), 107-131. Palinkas, L. A. u. a. (2015). Purposeful sampling for qualitative data collection and analysis in mixed method implementation research. Administration and Policy in Mental Health, 42(5), 533-544.', 'Schoonenboom, J. & Johnson, R. B. (2017). How to construct a mixed methods research design. Kölner Zeitschrift für Soziologie und Sozialpsychologie, 69 (Suppl 2), 107-131. Palinkas, L. A. et al. (2015). Purposeful sampling for qualitative data collection and analysis in mixed method implementation research. Administration and Policy in Mental Health, 42(5), 533-544.'),
      mitnehmen(
        P('Die Forschungsfrage entscheidet über die Erhebungsmethode, nicht die Gewohnheit.', 'The research question decides the data collection method, not habit.'),
        P('Wie verbreitet etwas ist, verlangt Breite; wie und warum etwas geschieht, verlangt Tiefe.', 'How widespread something is calls for breadth; how and why something happens calls for depth.'),
        P('Qualitativ endet die Auswahl bei Sättigung, quantitativ zielt die Stichprobe auf Verallgemeinerung.', 'Qualitatively, selection ends at saturation; quantitatively, the sample aims at generalisation.'),
        P('Mixed Methods verbindet beides, mit einem Zweck, der vorab überlegt wird.', 'Mixed methods connects both, with a purpose considered beforehand.')
      )
    ], ['fallzahl-ergaenzen', 'eh-faelle-interviews']),

  // ---------------------------------------------------------------- 2. Daten einlesen und prüfen
  a('eh-daten-einlesen', 'verstehen', P('Was mache ich mit dem Export aus einem Umfragedienst? (Datenimport, Plausibilitätsprüfung)', 'What do I do with the export from a survey service? (data import, plausibility check)'),
    P('Datenimport Export Umfragedienst Google Forms Microsoft Forms CSV Excel Mehrfachauswahl Mehrfachantworten doppelte Antworten Testfälle Plausibilität Plausibilitätsprüfung Wertebereich Schlüssel Daten-Check Platzhalter 99', 'data import export survey service Google Forms Microsoft Forms CSV Excel multiple choice multiple responses duplicate answers test cases plausibility plausibility check range of values key data check placeholder 99'),
    [
      { h: P('Kurz', 'In brief') },
      P('Ein Umfragedienst liefert die Antworten als Tabelle (CSV oder Excel). Bevor gerechnet wird, lohnt der Blick auf typische Fallen: mehrere Antworten in einer Zelle, doppelt abgeschickte Antworten, Testfälle des Teams und unmögliche Werte. Statable meldet beim Öffnen, was auffällt, und prüft mit Regeln, ob die Werte stimmen. Was ein Fehler ist, entscheidet die Forschungsfrage (Hilfe „Daten-Check“).', 'A survey service delivers the answers as a table (CSV or Excel). Before calculating, it pays to look for typical traps: several answers in one cell, answers submitted twice, test cases of the team and impossible values. On opening, Statable reports what stands out and checks with rules whether the values make sense. What counts as an error depends on the research question (help “Data check”).'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Der Ausschnitt eines Exports ist erfunden (kein echter Dienst, keine echten Personen). Finden Sie mindestens vier Auffälligkeiten und überlegen Sie, was Sie jeweils tun. Lesen Sie erst danach die Lösung.', 'The excerpt of an export is invented (no real service, no real people). Find at least four oddities and think about what you would do in each case. Only then read the solution.'),
      { tabelle: { kopf: [P('Zeile', 'Row'), P('Zeitstempel', 'Time stamp'), P('Name', 'Name'), P('Alter', 'Age'), P('Fächer (Mehrfachauswahl)', 'Subjects (multiple choice)'), P('Zufriedenheit (1-5)', 'Satisfaction (1-5)')], zeilen: [
        ['1', '05.11.2026 09:12', 'Mara K.', '21', P('Mathe, Physik', 'Maths, Physics'), '4'],
        ['2', '05.11.2026 09:15', 'Test Test', '99', P('Mathe', 'Maths'), '5'],
        ['3', '05.11.2026 09:31', 'Jonas P.', '24', P('Chemie', 'Chemistry'), '3'],
        ['4', '05.11.2026 09:31', 'Jonas P.', '24', P('Chemie', 'Chemistry'), '3'],
        ['5', '05.11.2026 10:02', 'Lea S.', '199', P('Physik, Chemie, Mathe', 'Physics, Chemistry, Maths'), '4'],
        ['6', '05.11.2026 10:40', 'Tom B.', '22', P('Mathe', 'Maths'), '7']
      ] } },
      { h: P('Lösung', 'Solution') },
      { ul: [
        P('Mehrere Antworten in einer Zelle (Zeilen 1 und 5): Die Spalte „Fächer“ enthält bei Mara zwei und bei Lea drei Fächer. Eine Zelle ist keine auswertbare Spalte. Besser eine Spalte je Fach mit 1 = angekreuzt und 0 = nicht angekreuzt; diese Spalten fasst man zu einem Mehrfachantworten-Set zusammen (Hilfe „Mehrfachantworten“).', 'Several answers in one cell (rows 1 and 5): the column “Subjects” holds two subjects for Mara and three for Lea. A cell is not an analysable column. Better one column per subject with 1 = ticked and 0 = not ticked; these columns are joined into a multiple response set (help “Multiple responses”).'),
        P('Doppelte Antwort (Zeilen 3 und 4): gleiche Person, gleicher Zeitstempel, gleiche Werte. Vermutlich wurde dieselbe Antwort zweimal exportiert. Der Assistent „Doppelte Fälle“ markiert Wiederholungen; gelöscht wird erst nach Rückfrage.', 'Duplicate answer (rows 3 and 4): same person, same time stamp, same values. Most likely the same answer was exported twice. The assistant “Duplicate cases” marks repetitions; deletion happens only after confirmation.'),
        P('Testfall (Zeile 2): Der Name „Test Test“ und das Alter 99 weisen auf einen Probelauf des Teams hin. Solche Zeilen gehören nicht in die Auswertung. Das Alter 99 kann zudem ein Platzhalter für „keine Angabe“ sein; der Daten-Check meldet den Verdacht.', 'Test case (row 2): the name “Test Test” and the age 99 point to a trial run by the team. Such rows do not belong in the analysis. The age 99 can also be a placeholder for “no answer”; the data check reports the suspicion.'),
        P('Unmöglicher Wert (Zeile 5): Alter 199. Eine Regel „Wertebereich“ (zum Beispiel Alter von 15 bis 90) in „Plausibilität prüfen“ listet die Zeile auf. Ob ein Tippfehler (19?) vorliegt, weiß nur, wer die Befragten kennt; Statable ändert nichts an den Daten.', 'Impossible value (row 5): age 199. A rule “range of values” (for example age from 15 to 90) in “Check plausibility” lists the row. Whether it is a typo (19?) only someone who knows the respondents can tell; Statable changes nothing in the data.'),
        P('Wert außerhalb der Skala (Zeile 6): Zufriedenheit 7 bei einer Skala von 1 bis 5. Ebenfalls ein Fall für die Regel „Wertebereich“.', 'Value outside the scale (row 6): satisfaction 7 on a scale from 1 to 5. Another case for the rule “range of values”.')
      ] },
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Die Datei öffnen (Seite „Daten“). Erkennt Statable einen Fragebogen, erscheint „Fragebogen erkannt - übernehmen?“; die Vorschläge prüfen, bevor sie übernommen werden.', 'Open the file (page “Data”). If Statable recognises a questionnaire, “Questionnaire recognised - adopt?” appears; check the suggestions before adopting them.'),
        P('Den Daten-Check lesen: Schreibweisen, auffällige Werte, Verdacht auf Platzhalter, leere Felder. Jeden Punkt bestätigen oder beheben.', 'Read the data check: spellings, unusual values, suspected placeholders, empty cells. Confirm or fix each item.'),
        P('Unter „Daten bearbeiten“ den Assistenten „Plausibilität prüfen“ öffnen: Regeln für Wertebereich, erlaubte Werte, Wenn-dann, Summe und eindeutigen Schlüssel anlegen. Er listet die Zeilen, die eine Regel verletzen.', 'Under “Edit data” open the assistant “Check plausibility”: set up rules for range of values, allowed values, if-then, sum and unique key. It lists the rows that violate a rule.'),
        P('Doppelte Antworten mit dem Assistenten „Doppelte Fälle“ markieren, am besten mit der Kennung als Vergleichsspalte.', 'Mark duplicate answers with the assistant “Duplicate cases”, preferably with the ID as comparison column.')
      ] },
      P('Für Exporte von Microsoft Forms, Nextcloud Forms, CryptPad und KoboToolbox gibt es eine Erkennung, für Google Forms nur eine Vermutung (der Aufbau dieser Datei ist nirgends beschrieben). Alles ist nach der Dokumentation erkannt, nicht an echten Exporten geprüft: Die Vorschläge sind zu prüfen. Danach gilt weiter der Daten-Check mit den Plausibilitätsregeln.', 'There is recognition for exports from Microsoft Forms, Nextcloud Forms, CryptPad and KoboToolbox, but only a guess for Google Forms (the structure of that file is described nowhere). Everything is recognised from the documentation, not checked against real exports: the suggestions must be checked. After that the data check with the plausibility rules still applies.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Eine Zeile, die gegen eine Plausibilitätsregel verstößt, wird von Statable automatisch gelöscht.', 'A row that violates a plausibility rule is deleted automatically by Statable.'),
        P('Die Prüfung listet nur auf und ändert nichts an den Daten. Ob ein auffälliger Wert ein Fehler ist, entscheidet die Forschungsfrage.', 'The check only lists and changes nothing in the data. Whether an unusual value is an error is decided by the research question.')),
      falsch(P('Der Wert 99 ist eine gewöhnliche Zahl und wird immer mitgerechnet.', 'The value 99 is an ordinary number and is calculated in every time.'),
        P('Werte wie 99 stehen oft für „keine Angabe“. Der Daten-Check meldet den Verdacht; wer ihn bestätigt, schließt diese Werte aus der Rechnung aus.', 'Values such as 99 often stand for “no answer”. The data check reports the suspicion; whoever confirms it excludes these values from the calculation.')),
      { h: P('Quellen', 'Sources') },
      P('Die Aussagen zu Statable stützen sich auf die Hilfe-Artikel „Stimmen die Werte in meinen Daten?“, „Daten-Check“, „Mehrfachantworten“ und „Daten vorbereiten“. Die Tabelle oben ist erfunden.', 'The statements about Statable rest on the help articles “Do the figures make sense?”, “Data check”, “Multiple responses” and “Preparing data”. The table above is invented.'),
      mitnehmen(
        P('Vor dem Rechnen den Export auf Fallen prüfen: mehrere Antworten in einer Zelle, Doppelte, Testfälle, unmögliche Werte.', 'Before calculating, check the export for traps: several answers in one cell, duplicates, test cases, impossible values.'),
        P('Mehrfachauswahl gehört in eine Spalte je Option mit 1 und 0.', 'Multiple choice belongs in one column per option with 1 and 0.'),
        P('Plausibilitätsregeln listen Verstöße auf und ändern nichts an den Daten.', 'Plausibility rules list violations and change nothing in the data.'),
        P('Was ein Fehler ist, entscheidet die Forschungsfrage, nicht die Prüfung.', 'What counts as an error is decided by the research question, not by the check.')
      )
    ], ['plausibilitaet', 'daten-check', 'frage-mehrfachantworten', 'daten-vorbereiten']),

  // ---------------------------------------------------------------- 3. Fälle für Interviews
  a('eh-faelle-interviews', 'verstehen', P('Wen interviewe ich nach dem Fragebogen? (Fallauswahl: extrem, typisch, abweichend, divers)', 'Whom do I interview after the questionnaire? (case selection: extreme, typical, deviant, diverse)'),
    P('Fallauswahl Interview Befragung gezielte Auswahl purposeful sampling extreme Fälle typische Fälle abweichende Fälle maximale Variation divers Sättigung Mixed Methods Verbinden connecting', 'case selection interview survey purposeful sampling extreme cases typical cases deviant cases maximum variation diverse saturation mixed methods connecting'),
    [
      { h: P('Kurz', 'In brief') },
      P('Nach dem Fragebogen sollen einige Personen interviewt werden. Welche, ist keine Zufallsfrage, sondern eine Entscheidung mit Absicht: Wollen Sie aus Ungewöhnlichem lernen (extreme oder abweichende Fälle), zeigen, was normal ist (typische Fälle), oder die Bandbreite abbilden (maximale Variation, hier „divers“)? Dass die Interviewten aus den Befragten gezogen werden, heißt in der Fachsprache Verbinden (connecting; Fetters, Curry und Creswell, 2013).', 'After the questionnaire a few people are to be interviewed. Which ones is not a matter of chance but a decision made on purpose: do you want to learn from the unusual (extreme or deviant cases), show what is normal (typical cases) or cover the range (maximum variation, here “diverse”)? That the interviewees are drawn from the respondents is called connecting in technical language (Fetters, Curry and Creswell, 2013).'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Sieben Studierende haben einen Fragebogen ausgefüllt. Die Zahlen sind erfunden. Wählen Sie drei für ein Interview, nennen Sie je eine Regel (extrem, typisch, abweichend oder divers) und die Frage, die Sie damit beantworten wollen. Lesen Sie erst danach die Lösung.', 'Seven students filled in a questionnaire. The numbers are invented. Choose three for an interview, name a rule for each (extreme, typical, deviant or diverse) and the question you want to answer with it. Only then read the solution.'),
      { tabelle: { kopf: [P('Fall', 'Case'), P('Zufriedenheit mit dem Studium (1-10)', 'Satisfaction with studies (1-10)'), P('Nebenjob (Stunden pro Woche)', 'Side job (hours per week)')], zeilen: [
        ['A', '9', '4'], ['B', '7', '10'], ['C', '2', '18'], ['D', '4', '3'], ['E', '8', '6'], ['F', '5', '15'], ['G', '10', '2']
      ] } },
      { h: P('Lösung', 'Solution') },
      { ul: [
        P('Extrem: C (Zufriedenheit 2, der niedrigste Wert) und G (10, der höchste). Frage: Was unterscheidet die Unzufriedensten von den Zufriedensten? Vorsicht: Ganz am Rand liegende Fälle können als zu außergewöhnlich abgetan werden (Palinkas u. a., 2015); fragen Sie sich, ob C und G das Gemeinsame erhellen.', 'Extreme: C (satisfaction 2, the lowest value) and G (10, the highest). Question: what separates the least satisfied from the most satisfied? Caution: cases right at the edge can be dismissed as too unusual (Palinkas et al., 2015); ask yourself whether C and G illuminate what is common.'),
        P('Typisch: B. Der Median der sieben Zufriedenheitswerte (2, 4, 5, 7, 8, 9, 10) ist 7; B liegt genau darauf. Frage: Wie erleben Studierende in der Mitte ihr Studium? Ein typischer Fall beschreibt, er gilt nicht für alle.', 'Typical: B. The median of the seven satisfaction values (2, 4, 5, 7, 8, 9, 10) is 7; B lies exactly on it. Question: how do students in the middle experience their studies? A typical case describes; it does not hold for everyone.'),
        P('Abweichend: D. Je mehr Stunden im Nebenjob, desto niedriger die Zufriedenheit (C, F, B, A, E, G folgen diesem Muster). D hat nur 3 Stunden und trotzdem Zufriedenheit 4. Frage: Was steckt hinter D, das die Zahlen nicht zeigen?', 'Deviant: D. The more hours in the side job, the lower the satisfaction (C, F, B, A, E, G follow this pattern). D has only 3 hours and still satisfaction 4. Question: what lies behind D that the numbers do not show?'),
        P('Divers (maximale Variation): zum Beispiel C, B und G, also unten, Mitte, oben. Frage: Welche Bandbreite von Erfahrungen gibt es? Hier ist wichtig, dass die Fälle verschieden sind, nicht dass jeder für sich typisch ist.', 'Diverse (maximum variation): for example C, B and G, that is bottom, middle, top. Question: what range of experiences exists? Here it matters that the cases differ, not that each is typical by itself.')
      ] },
      P('Es gibt keine einzig richtige Auswahl. Eine gute Antwort nennt Regel und Frage. Und: Die Zahlen sind erfunden und beweisen nichts; sie dienen nur dazu, Fälle zu finden, die man dann im Gespräch genauer betrachtet.', 'There is no single right selection. A good answer names the rule and the question. And: the numbers are invented and prove nothing; they only serve to find cases that are then looked at more closely in conversation.'),
      { h: P('Die Regeln im Überblick', 'The rules at a glance') },
      P('Nach Palinkas und Kollegen (2015) erweitern manche Strategien die Bandbreite der Unterschiede (maximale Variation, extreme Fälle), ähnlich wie Streuungsmaße. Andere engen sie ein (typische Fälle), ähnlich wie Lagemaße. Extreme oder abweichende Fälle dienen dazu, aus ungewöhnlichen Erscheinungen zu lernen; maximale Variation erfasst unterschiedliche Ausprägungen und gemeinsame Muster quer dazu; typische Fälle zeigen, was normal oder durchschnittlich ist, ohne für alle Teilnehmenden zu verallgemeinern. Eine Auswahl nach festem Kriterium eignet sich, um aus standardisierten Fragebögen Fälle für eine vertiefende Nachfrage zu finden.', 'According to Palinkas and colleagues (2015), some strategies widen the range of differences (maximum variation, extreme cases), like measures of dispersion. Others narrow it (typical cases), like measures of central tendency. Extreme or deviant cases serve to learn from unusual manifestations; maximum variation captures diverse variations and common patterns across them; typical cases show what is normal or average without generalising to all participants. Selection by a fixed criterion suits picking out cases from standardised questionnaires for an in-depth follow-up.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Das Beispiel „Praktikum im Lehramt: Zahlen und Interviews“ öffnen (Lernen oder Beispiele) und die Karte „Fälle vergleichen“ wählen.', 'Open the example “Teaching practicum: numbers and interviews” (learning or examples) and choose the card “Comparing cases”.'),
        P('Unter der Tabelle „Fälle für Interviews vorschlagen“ aufklappen, eine Regel wählen (extrem, typisch, abweichend oder maximale Variation), die Spalte wählen und die Zahl der Fälle einstellen.', 'Below the table open “Suggest cases for interviews”, choose a rule (extreme, typical, deviant or maximum variation), choose the column and set the number of cases.'),
        P('In der Liste steht je Fall der Rechenwert und die Begründung. Fälle anhaken und als eigene Gruppe übernehmen; „Rückgängig“ nimmt die Übernahme zurück.', 'The list shows the calculated value and the reason for each case. Tick cases and adopt them as a group of their own; “Undo” takes the adoption back.')
      ] },
      P('Statable wählt nie von selbst aus und schreibt nie in die Daten: Es liefert nur eine geordnete Liste, entschieden wird von Ihnen.', 'Statable never selects by itself and never writes into the data: it only provides an ordered list; you decide.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Der typische Fall zeigt, was für alle Befragten gilt.', 'The typical case shows what holds for all respondents.'),
        P('Er beschreibt und veranschaulicht, was normal oder durchschnittlich ist. Verallgemeinern lässt er sich nicht (Palinkas u. a., 2015).', 'It describes and illustrates what is normal or average. It cannot be generalised (Palinkas et al., 2015).')),
      falsch(P('Für Interviews nach einer Befragung wird zufällig gelost, damit die Auswahl neutral bleibt.', 'For interviews after a survey cases are drawn at random so that the selection stays neutral.'),
        P('In der qualitativen Teilstudie wählt man gezielt nach dem, was man verstehen will. Ein Zufallsausschnitt wäre für wenige Interviews zu klein, um Besonderes oder die Bandbreite zu zeigen.', 'In the qualitative part of a study one chooses on purpose according to what one wants to understand. A random draw would be too small for a few interviews to show the special or the range.')),
      { h: P('Quellen', 'Sources') },
      P('Palinkas, L. A. u. a. (2015). Purposeful sampling for qualitative data collection and analysis in mixed method implementation research. Administration and Policy in Mental Health, 42(5), 533-544. Fetters, M. D., Curry, L. A. & Creswell, J. W. (2013). Achieving integration in mixed methods designs - principles and practices. Health Services Research, 48(6 Pt 2), 2134-2156. Die Zahlen in „Selbst machen“ sind erfunden.', 'Palinkas, L. A. et al. (2015). Purposeful sampling for qualitative data collection and analysis in mixed method implementation research. Administration and Policy in Mental Health, 42(5), 533-544. Fetters, M. D., Curry, L. A. & Creswell, J. W. (2013). Achieving integration in mixed methods designs - principles and practices. Health Services Research, 48(6 Pt 2), 2134-2156. The numbers in “Do it yourself” are invented.'),
      mitnehmen(
        P('Interviewfälle werden gezielt gewählt, nicht gelost, und zu jeder Wahl gehört eine Frage.', 'Interview cases are chosen on purpose, not drawn by lot, and every choice comes with a question.'),
        P('Extreme und abweichende Fälle lehren aus Ungewöhnlichem, typische Fälle zeigen das Normale, maximale Variation zeigt die Bandbreite.', 'Extreme and deviant cases teach from the unusual, typical cases show the normal, maximum variation shows the range.'),
        P('Ein typischer Fall beschreibt und verallgemeinert nicht.', 'A typical case describes and does not generalise.'),
        P('Statable liefert nur Vorschläge; die Auswahl bleibt Ihre Entscheidung.', 'Statable only gives suggestions; the selection remains your decision.')
      )
    ], ['frage-faelle', 'eh-meta-inferenz']),

  // ---------------------------------------------------------------- 4. Meta-Inferenz
  a('eh-meta-inferenz', 'verstehen', P('Was lerne ich aus beiden zusammen? (Meta-Inferenz: Bestätigung, Erweiterung, Widerspruch)', 'What do I learn from both together? (meta-inference: confirmation, expansion, discordance)'),
    P('Meta-Inferenz Passung Fit Bestätigung Erweiterung Widerspruch Integration Joint Display Mixed Methods Zahlen Zitate Quantitizing Fallvergleich gemischte Tabelle', 'meta-inference fit confirmation expansion discordance integration joint display mixed methods numbers quotes quantitizing case comparison mixed table'),
    [
      { h: P('Kurz', 'In brief') },
      P('Liegen zu denselben Fällen Zahlen und Aussagen vor, fragt man, wie beides zusammenpasst. Diese Passung (fit) hat drei Ausgänge (Fetters, Curry und Creswell, 2013): Bestätigung (beide kommen zum gleichen Schluss), Erweiterung (die Aussagen beleuchten etwas anderes an derselben Sache) und Widerspruch (beide stehen im Konflikt). Die Meta-Inferenz ist der Schluss, der sich aus beiden Datenarten zusammen ziehen lässt.', 'If numbers and statements exist for the same cases, one asks how the two fit together. This fit has three outcomes (Fetters, Curry and Creswell, 2013): confirmation (both reach the same conclusion), expansion (the statements light up something else about the same thing) and discordance (the two conflict). The meta-inference is the conclusion that can be drawn from both kinds of data together.'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Die drei Paare aus Kennzahl und Zitat sind erfunden (keine echte Studie, keine echten Personen). Bestimmen Sie zu jedem Paar die Passung: Bestätigung, Erweiterung oder Widerspruch. Lesen Sie erst danach die Lösung.', 'The three pairs of figure and quote are invented (no real study, no real people). For each pair determine the fit: confirmation, expansion or discordance. Only then read the solution.'),
      { tabelle: { kopf: [P('Paar', 'Pair'), P('Kennzahl (erfunden)', 'Figure (invented)'), P('Zitat (erfunden)', 'Quote (invented)'), P('Ihre Passung', 'Your fit')], zeilen: [
        ['1', P('Selbstwirksamkeit im Mittel 4,2 von 5 (6 Studierende)', 'Self-efficacy mean 4.2 of 5 (6 students)'), P('„Im Unterricht fühle ich mich sicher, ich traue mir fast jede Situation zu.“', '“In class I feel confident, I trust myself with almost any situation.”'), '?'],
        ['2', P('Praktikumsnote im Mittel 1,8 (sehr gut)', 'Practicum grade mean 1.8 (very good)'), P('„Die Note sagt wenig. Entscheidend war, dass ich nach der dritten Woche überhaupt Zugang zu den Kindern fand; vorher hat mich jeder Tag viel Kraft gekostet.“', '“The grade says little. What mattered was that after the third week I found access to the children at all; before that every day cost me a lot of energy.”'), '?'],
        ['3', P('Zufriedenheit mit der Betreuung 4,5 von 5 (hoch)', 'Satisfaction with supervision 4.5 of 5 (high)'), P('„Betreut hat mich eigentlich niemand, ich war meistens allein in der Klasse.“', '“Nobody really supervised me, I was alone in the class most of the time.”'), '?']
      ] } },
      { h: P('Lösung', 'Solution') },
      { ol: [
        P('Bestätigung. Hohe Zahl, und das Zitat sagt dasselbe in eigenen Worten. Beide Datenarten kommen zum gleichen Schluss; das Ergebnis wird glaubwürdiger. Meta-Inferenz, zum Beispiel: Diese Gruppe fühlt sich sicher, und sie beschreibt es auch so.', 'Confirmation. High figure, and the quote says the same in its own words. Both kinds of data reach the same conclusion; the result becomes more credible. Meta-inference, for example: this group feels confident, and describes it that way.'),
        P('Erweiterung. Die Note ist gut, das Zitat widerspricht ihr nicht, zeigt aber, was die Note nicht zeigt: wie der Weg dorthin verlief. Die Ergebnisse gehen auseinander und beleuchten verschiedene Seiten derselben Sache, hier Ergebnis und Erleben. Meta-Inferenz, zum Beispiel: Eine gute Note kann einen schweren Anfang verbergen.', 'Expansion. The grade is good, the quote does not contradict it but shows what the grade does not show: how the way there went. The results diverge and light up different sides of the same thing, here result and experience. Meta-inference, for example: a good grade can hide a hard start.'),
        P('Widerspruch. Hohe Zufriedenheit, aber das Zitat beschreibt fehlende Betreuung. Beides passt nicht zusammen. Das ist kein Grund, eine Seite zu verwerfen: Mögliche Wege sind nach Verzerrungen und nach Annahmen des Vorgehens zu suchen (wurde nach „Betreuung“ in beiden Fällen dasselbe gemeint?), weitere Daten zu erheben oder eine Erklärung in der Theorie zu suchen (Fetters, Curry und Creswell, 2013).', 'Discordance. High satisfaction, but the quote describes missing supervision. The two do not fit together. That is no reason to discard one side: possible routes are to look for bias and for the assumptions of the procedure (did “supervision” mean the same in both cases?), to collect more data or to look for an explanation in theory (Fetters, Curry and Creswell, 2013).')
      ] },
      { h: P('Warum nicht einfach Zitate zählen?', 'Why not simply count quotes?') },
      P('Wer Texte in Zahlen überführt (quantitizing), erhält einen quantitativen Datensatz. Wertet man diesen statistisch aus, ist das eine quantitative und keine gemischte Analyse (Schoonenboom, 2023). Gemischt wird erst, wenn Zahlen und Texte der Fälle gemeinsam betrachtet werden, zum Beispiel in einer Tabelle mit mindestens einer Zahlenspalte und einer Textspalte. Außerdem tragen Texte mehr Bedeutung als der verdichtete Zahlenwert: Derselbe Wert „mittel“ kann in den Texten sehr verschiedene Vorgänge verbergen.', 'Whoever turns texts into numbers (quantitizing) gets a quantitative dataset. Analysing it statistically is a quantitative and not a mixed analysis (Schoonenboom, 2023). It only becomes mixed when the numbers and texts of the cases are looked at together, for example in a table with at least one number column and one text column. In addition, texts carry more meaning than the condensed figure: the same value “moderate” can hide very different processes in the texts.'),
      { h: P('Wo kommen die Daten zusammen?', 'Where do the data come together?') },
      P('Jede echte Mixed-Methods-Studie hat mindestens einen Integrationspunkt, an dem die qualitativen und quantitativen Teile zusammengebracht werden. Meist geschieht das beim Schreiben der Ergebnisse, zum Beispiel mit einem Joint Display (Schoonenboom und Johnson, 2017): Zahlen und passende Zitate stehen nebeneinander, um Einsichten zu gewinnen, die über die getrennten Ergebnisse hinausgehen (Fetters, Curry und Creswell, 2013).', 'Each true mixed methods study has at least one point of integration at which the qualitative and quantitative parts are brought together. Mostly this happens when writing up the results, for example with a joint display (Schoonenboom and Johnson, 2017): numbers and matching quotes stand side by side to gain insights beyond the separate results (Fetters, Curry and Creswell, 2013).'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Das Beispiel „Praktikum im Lehramt: Zahlen und Interviews“ öffnen und die Karte „Fälle vergleichen“ wählen: Zahlen und Interviewzitate stehen je Fall nebeneinander, die Fälle bilden Gruppen.', 'Open the example “Teaching practicum: numbers and interviews” and choose the card “Comparing cases”: numbers and interview quotes stand next to each other for each case, the cases form groups.'),
        P('Je Gruppe die Passung wählen (Bestätigung, Erweiterung oder Widerspruch) und die Meta-Inferenz im Textfeld der Gruppe schreiben.', 'For each group choose the fit (confirmation, expansion or discordance) and write the meta-inference in the text field of the group.'),
        P('Statable zählt nur, wie oft Sie welche Passung gewählt haben, und bewertet nichts. Auf der Seite „Bericht“ beantworten Sie vier Fragen zur Integration; die Antworten stehen im Word-Bericht.', 'Statable only counts how often you chose which fit and judges nothing. On the page “Report” you answer four questions on integration; the answers appear in the Word report.')
      ] },
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Erweiterung heißt, die Zitate bestätigen die Zahlen noch einmal mit anderen Worten.', 'Expansion means the quotes confirm the numbers once more in other words.'),
        P('Das wäre Bestätigung. Bei Erweiterung gehen die Ergebnisse auseinander und beleuchten verschiedene Seiten derselben Sache, etwa Stärke und Art eines Zusammenhangs (Fetters, Curry und Creswell, 2013).', 'That would be confirmation. With expansion the results diverge and light up different sides of the same thing, such as strength and nature of an association (Fetters, Curry and Creswell, 2013).')),
      falsch(P('Bei einem Widerspruch ist eine der beiden Datenarten fehlerhaft und fällt weg.', 'With a discordance one of the two kinds of data is faulty and is dropped.'),
        P('Ein Widerspruch ist ein Ausgangspunkt für weitere Analyse: nach Verzerrungen suchen, weitere Daten erheben oder eine umfassendere Theorie finden, die beide Ergebnisse erklärt (Schoonenboom und Johnson, 2017).', 'A discordance is a starting point for further analysis: looking for bias, collecting more data or finding a more comprehensive theory that accounts for both results (Schoonenboom and Johnson, 2017).')),
      { h: P('Quellen', 'Sources') },
      P('Fetters, M. D., Curry, L. A. & Creswell, J. W. (2013). Achieving integration in mixed methods designs - principles and practices. Health Services Research, 48(6 Pt 2), 2134-2156. Schoonenboom, J. (2023). The fundamental difference between qualitative and quantitative data in mixed methods research. Forum Qualitative Sozialforschung, 24(1), Art. 11. Schoonenboom, J. & Johnson, R. B. (2017). How to construct a mixed methods research design. Kölner Zeitschrift für Soziologie und Sozialpsychologie, 69 (Suppl 2), 107-131. Die Paare in „Selbst machen“ sind erfunden.', 'Fetters, M. D., Curry, L. A. & Creswell, J. W. (2013). Achieving integration in mixed methods designs - principles and practices. Health Services Research, 48(6 Pt 2), 2134-2156. Schoonenboom, J. (2023). The fundamental difference between qualitative and quantitative data in mixed methods research. Forum Qualitative Sozialforschung, 24(1), Art. 11. Schoonenboom, J. & Johnson, R. B. (2017). How to construct a mixed methods research design. Kölner Zeitschrift für Soziologie und Sozialpsychologie, 69 (Suppl 2), 107-131. The pairs in “Do it yourself” are invented.'),
      mitnehmen(
        P('Passung hat drei Ausgänge: Bestätigung, Erweiterung, Widerspruch.', 'Fit has three outcomes: confirmation, expansion, discordance.'),
        P('Die Meta-Inferenz ist der Schluss aus Zahlen und Aussagen zusammen; ihn zieht der Mensch, nicht die Software.', 'The meta-inference is the conclusion from numbers and statements together; the person draws it, not the software.'),
        P('Ein Widerspruch ist ein Anlass zu weiterer Analyse, kein Grund, eine Seite zu verwerfen.', 'A discordance is a reason for further analysis, not a reason to discard one side.'),
        P('Texte in Zahlen zu überführen und statistisch auszuwerten ist quantitativ; gemischt wird erst bei gemeinsamer Betrachtung.', 'Turning texts into numbers and analysing them statistically is quantitative; it becomes mixed only when looked at together.')
      )
    ], ['frage-faelle', 'eh-faelle-interviews']),

  // ---------------------------------------------------------------- 5. Qualitätsprüfung von Fragebögen (Erheben, Paket 2D)
  a('eh-qualitaet', 'verstehen', P('Qualitätsprüfung von Fragebögen (Hinweise nach festen Regeln)', 'Quality check of questionnaires (hints by fixed rules)'),
    P('Qualitätsprüfung Fragebogen Hinweise Regeln Doppelfrage Verneinung Suggestivfrage lange Frage Skala ausgewogen Mitte Matrix Barrierefreiheit Alternativtext Farbe Lesbarkeitsformel', 'quality check questionnaire hints rules double-barreled question negation leading question long question balanced scale midpoint grid accessibility alternative text colour readability formula'),
    [
      { h: P('Kurz', 'In brief') },
      P('Statable prüft die Fragen eines Fragebogen-Plans nach festen Regeln und zeigt Hinweise. Die Hinweise sind Vorschläge, keine Urteile: Was passt, entscheiden Sie. Eine Frage, bei der ein Hinweis nicht zutrifft, lässt sich als „geprüft, passt so“ abhaken; das wird im Plan gespeichert. Statable benutzt keine Lesbarkeitsformel, denn solche Formeln sagen die Verständlichkeit von Fragen schlecht vorher (Lenzner, 2014).', 'Statable checks the questions of a questionnaire plan by fixed rules and shows hints. The hints are suggestions, not verdicts: you decide what fits. When a hint does not apply to a question, you can tick it off as “checked, fine as it is”; this is saved in the plan. Statable uses no readability formula, because such formulas predict the comprehensibility of questions poorly (Lenzner, 2014).'),
      { h: P('Die Regeln, je ein Satz und die Quelle', 'The rules, one sentence each and the source') },
      { ul: [
        P('Doppelfrage (double-barreled question): Die Frage fragt vielleicht nach zwei Dingen zugleich. Ausgelöst, wenn „und“ oder „oder“ von einem Wort wie „Ihre“, „die“ oder „sind“ gefolgt wird, nicht bei Aufzählungen. Quelle: Lenzner und Menold (2016), Abschnitt 2.6.', 'Double-barreled question: The question may ask about two things at once. Triggered when “and” or “or” is followed by a word such as “your”, “the” or “are”, not for simple lists. Source: Lenzner and Menold (2016), section 2.6.'),
        P('Doppelte Verneinung (double negative): zwei Verneinungswörter im Text, oder ein Verneinungswort und eine Antwort wie „lehne ab“. Die Quelle nennt auch einzelne Verneinungen; die Regel ist enger. Quelle: Lenzner und Menold (2016), Abschnitt 2.7.', 'Double negative: two negation words in the text, or one negation word and an answer such as “disagree”. The source also names single negations; the rule is narrower. Source: Lenzner and Menold (2016), section 2.7.'),
        P('Suggestivfrage (leading question): Der Anfang erinnert an Formulierungen wie „Finden Sie nicht auch“. Die Anfänge in der Liste sind nur Beispiele und nur ein Teil dessen, was die Quelle meint. Quelle: Lenzner und Menold (2016), Abschnitt 2.9.', 'Leading question: The opening resembles wordings such as “Don’t you think”. The openings in the list are only examples and only part of what the source means. Source: Lenzner and Menold (2016), section 2.9.'),
        P('Lange Frage (long question): mehr als 25 Wörter. Das ist eine Faustregel und eine eigene Festlegung von Statable, nicht aus der Quelle; belegt ist nur, dass einfache Satzstrukturen leichter zu verstehen sind. Quelle: Lenzner und Menold (2016), Abschnitt 2.4.', 'Long question: more than 25 words. This is a rule of thumb and Statable’s own choice, not from the source; what is supported is only that simple sentence structures are easier to understand. Source: Lenzner and Menold (2016), section 2.4.'),
        P('Unausgewogene Skala (unbalanced scale): Bei einer bekannten Zustimmungs- oder Zufriedenheitsskala gibt es nicht gleich viele positive und negative Stufen. Unbekannte Beschriftungen werden nicht beurteilt. Quelle: Menold und Bogner (2016), Abschnitt 3.', 'Unbalanced scale: A known agreement or satisfaction scale does not have as many positive as negative levels. Unknown labels are not assessed. Source: Menold and Bogner (2016), section 3.'),
        P('Skala ohne Mitte (scale with no midpoint): Eine geordnete Skala hat eine gerade Zahl von Stufen (mindestens vier, ohne „weiß nicht“). Das kann Absicht sein; der Hinweis fragt nur danach. Quelle: Menold und Bogner (2016), Abschnitt 6.', 'Scale with no midpoint: An ordered scale has an even number of levels (at least four, not counting “don’t know”). This may be intended; the hint only asks about it. Source: Menold and Bogner (2016), section 6.'),
        P('Große Matrix (large grid): ein Block mit mehr als 7 Items oder mehr als 7 Stufen. Die Zahl 7 ist eine Faustregel und eine eigene Festlegung; belegt sind Abbrüche, fehlende Angaben und gleichförmige Antworten bei Matrizen in Webumfragen. Quelle: Couper, Tourangeau, Conrad und Zhang (2013).', 'Large grid: a block with more than 7 items or more than 7 levels. The number 7 is a rule of thumb and our own choice; what is supported is break-offs, missing answers and straight-lining in grids in web surveys. Source: Couper, Tourangeau, Conrad and Zhang (2013).'),
        P('Bild ohne Alternativtext (alternative text): Menschen mit Screenreader erfahren sonst nicht, was zu sehen ist. Quelle: WCAG 2.2, Erfolgskriterium 1.1.1.', 'Image without alternative text: People with a screen reader would not learn what is shown. Source: WCAG 2.2, success criterion 1.1.1.'),
        P('Skala nur mit Zahlen (scale with numbers only): Eine Stufe hat als Text nur eine Zahl oder „3 von 5“. Sichtbar sind dann nur Zahlen. Quelle: WCAG 2.2, Erfolgskriterium 1.3.1, und Menold und Bogner (2016), Abschnitt 3.', 'Scale with numbers only: A level has only a number or “3 of 5” as its text. Only numbers are visible then. Source: WCAG 2.2, success criterion 1.3.1, and Menold and Bogner (2016), section 3.'),
        P('Farbe als Unterscheidung (colour only): Ein Text nennt eine Farbe zusammen mit „Feld“, „Kreis“ oder „markiert“. Die Regel sucht nur Wörter; ob die Farbe wirklich allein unterscheidet, beurteilt die Person. Quelle: WCAG 2.2, Erfolgskriterium 1.4.1.', 'Colour only: A text names a colour together with “field”, “circle” or “marked”. The rule only looks for words; whether colour really is the only distinction is for the person to judge. Source: WCAG 2.2, success criterion 1.4.1.'),
        P('Doppelte oder ungültige Namen, Antwortoption ohne Text und nie erfüllbare Bedingungen kommen aus der Planprüfung und erscheinen hier mit.', 'Duplicate or invalid names, an answer option without text and conditions that can never be met come from the plan check and appear here too.')
      ] },
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ul: [
        P('Die Prüfung läuft in der Sprache, die Sie gerade ansehen; Texte in der anderen Sprache werden dabei nicht angesehen.', 'The check runs in the language you are looking at; texts in the other language are not looked at.'),
        P('Es gibt höchstens einen Hinweis je Regel und Frage. Abhaken gilt nur für diese Regel an dieser Frage.', 'There is at most one hint per rule and question. Ticking off applies only to that rule at that question.'),
        P('Fehler der Planprüfung (zum Beispiel ein doppelter Name) lassen sich nicht abhaken; sie sperren den Export.', 'Errors of the plan check (for example a duplicate name) cannot be ticked off; they block the export.')
      ] },
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Wenn Statable keinen Hinweis zeigt, ist die Frage gut.', 'If Statable shows no hint, the question is good.'),
        P('Die Regeln fangen nur einige bekannte Schwächen ab, mit Wortlisten und Schwellen. Ob eine Frage verständlich ist, zeigt ein Pretest mit echten Menschen.', 'The rules only catch some known weaknesses, using word lists and thresholds. Whether a question is understandable is shown by a pretest with real people.')),
      { h: P('Quellen', 'Sources') },
      P('Lenzner, T. & Menold, N. (2016). Question Wording. GESIS Survey Guidelines. Menold, N. & Bogner, K. (2016). Design of Rating Scales in Questionnaires. GESIS Survey Guidelines. Couper, M. P., Tourangeau, R., Conrad, F. G. & Zhang, C. (2013). The Design of Grids in Web Surveys. Social Science Computer Review, 31(3), 322-345. Lenzner, T. (2014). Are readability formulas valid tools for assessing survey question difficulty? Sociological Methods & Research, 43(4), 677-698. W3C (2024). Web Content Accessibility Guidelines (WCAG) 2.2.', 'Lenzner, T. & Menold, N. (2016). Question Wording. GESIS Survey Guidelines. Menold, N. & Bogner, K. (2016). Design of Rating Scales in Questionnaires. GESIS Survey Guidelines. Couper, M. P., Tourangeau, R., Conrad, F. G. & Zhang, C. (2013). The Design of Grids in Web Surveys. Social Science Computer Review, 31(3), 322-345. Lenzner, T. (2014). Are readability formulas valid tools for assessing survey question difficulty? Sociological Methods & Research, 43(4), 677-698. W3C (2024). Web Content Accessibility Guidelines (WCAG) 2.2.'),
      mitnehmen(
        P('Die Hinweise sind Vorschläge; was passt, entscheiden Sie.', 'The hints are suggestions; you decide what fits.'),
        P('Jede Regel hat eine Quelle; Schwellen wie 25 Wörter oder 7 Items sind eigene Festlegungen und so gekennzeichnet.', 'Every rule has a source; thresholds such as 25 words or 7 items are our own choices and labelled as such.'),
        P('Eine Lesbarkeitsformel gibt es nicht, weil sie die Verständlichkeit von Fragen schlecht vorhersagt.', 'There is no readability formula, because it predicts the comprehensibility of questions poorly.'),
        P('Ein Pretest mit echten Menschen ersetzt keine Regel, und keine Regel ersetzt ihn.', 'A pretest with real people replaces no rule, and no rule replaces it.')
      )
    ], ['eh-methode'])
];
